const src: string = "data:image/png;base64,';\n  ['navLogo','heroLogoImg'].forEach(id=>{\n    const el=document.getElementById(id);\n    if(el){el.src=LOGO;el.onerror=function(){this.style.display='none';};}\n  });\n})();\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 CURSOR \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n(function(){\n  const dot=document.getElementById('cursorDot');\n  const ring=document.getElementById('cursorRing');\n  if(!dot||!ring)return;\n  let mx=0,my=0,rx=0,ry=0;\n  document.addEventListener('mousemove',e=>{mx=e.clientX;my=e.clientY;dot.style.left=mx+'px';dot.style.top=my+'px';});\n  function animRing(){rx+=(mx-rx)*0.12;ry+=(my-ry)*0.12;ring.style.left=rx+'px';ring.style.top=ry+'px';requestAnimationFrame(animRing);}\n  animRing();\n  document.querySelectorAll('a,button,.card,.pillar,.chapter-item,.article-card').forEach(el=>{\n    el.addEventListener('mouseenter',()=>{ring.style.width='54px';ring.style.height='54px';ring.style.borderColor='var(--gold)';});\n    el.addEventListener('mouseleave',()=>{ring.style.width='36px';ring.style.height='36px';ring.style.borderColor='rgba(201,160,32,0.5)';});\n  });\n})();\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 NAVBAR SCROLL \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nwindow.addEventListener('scroll',()=>{\n  const nav=document.getElementById('navbar');\n  if(window.scrollY>40){nav.classList.add('scrolled');}\n  else{nav.classList.remove('scrolled');}\n},{passive:true});\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 PAGE NAVIGATION \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nfunction showPage(id){\n  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));\n  const target=document.getElementById('page-'+id);\n  if(target){target.classList.add('active');}\n  window.scrollTo({top:0,behavior:'smooth'});\n  closeMobile();\n  setTimeout(()=>initReveal(),100);\n}\nfunction goMob(id){showPage(id);}\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 MOBILE NAV \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nfunction toggleMobile(){\n  const nav=document.getElementById('mobileNav');\n  const btn=document.getElementById('hamburger');\n  nav.classList.toggle('open');\n  btn.classList.toggle('open');\n  document.body.style.overflow=nav.classList.contains('open')?'hidden':'';\n}\nfunction closeMobile(){\n  document.getElementById('mobileNav').classList.remove('open');\n  document.getElementById('hamburger').classList.remove('open');\n  document.body.style.overflow='';\n}\nwindow.addEventListener('resize',()=>{if(window.innerWidth>768)closeMobile();});\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 FAQ \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nfunction toggleFaq(btn){\n  const body=btn.nextElementSibling;\n  const icon=btn.querySelector('.faq-icon');\n  const open=body.classList.contains('open');\n  document.querySelectorAll('.faq-a.open').forEach(b=>b.classList.remove('open'));\n  document.querySelectorAll('.faq-icon.open').forEach(i=>i.classList.remove('open'));\n  if(!open){body.classList.add('open');icon.classList.add('open');}\n}\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 FILTER \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nfunction setFilter(btn){\n  document.querySelectorAll('.filter-btn').forEach(b=>b.classList.remove('active'));\n  btn.classList.add('active');\n}\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 SCROLL REVEAL \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\nfunction initReveal(){\n  const opts={threshold:0.1,rootMargin:'0px 0px -40px 0px'};\n  const obs=new IntersectionObserver((entries)=>{\n    entries.forEach(e=>{\n      if(e.isIntersecting){e.target.classList.add('visible');obs.unobserve(e.target);}\n    });\n  },opts);\n  document.querySelectorAll('.page.active .reveal,.page.active .reveal-left,.page.active .reveal-right,.page.active .reveal-scale').forEach(el=>{\n    obs.observe(el);\n  });\n}\n\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550 INIT \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550";
export const LOGO_SRC = src;
